import {makeItauDemo} from '../js/banks/itau-demo.js';
import test from 'node:test';import assert from 'node:assert/strict';import {readFile} from 'node:fs/promises';import vm from 'node:vm';import {makeDemo} from '../js/demo.js';
test('index carrega script clássico pronto para abrir como arquivo',async()=>{const html=await readFile(new URL('../index.html',import.meta.url),'utf8');assert.ok(html.includes('defer src="./js/app.bundle.js'));assert.equal(html.includes('type="module"'),false);assert.ok(html.includes("worker-src 'self' blob:"));new vm.Script(await readFile(new URL('../js/app.bundle.js',import.meta.url),'utf8'));});
test('worker empacotado executa a mesma validação sem importar arquivos',async()=>{let message;const self={postMessage:data=>{message=data;}};const source=await readFile(new URL('../js/validation-worker.bundle.js',import.meta.url),'utf8');await new vm.Script(source).runInNewContext({self,TextDecoder,TextEncoder,Uint8Array,Date,URL});await self.onmessage({data:{bytes:new TextEncoder().encode(makeDemo()),options:{referenceDate:'2030-01-15',expectedIdentification:'12345001234567'}}});assert.equal(message.error,undefined);assert.equal(message.result.titleCount,3);assert.equal(message.result.summary.errors,0);assert.equal(message.result.totalCents,'60000');});

test('worker empacotado carrega o módulo Itaú e gera diagnóstico independente',async()=>{let message;const self={postMessage:data=>{message=data;}};const source=await readFile(new URL('../js/validation-worker.bundle.js',import.meta.url),'utf8');await new vm.Script(source).runInNewContext({self,TextDecoder,TextEncoder,Uint8Array,Date,URL});await self.onmessage({data:{bytes:new TextEncoder().encode(makeItauDemo()),options:{bank:'341',layout:'400',referenceDate:'2030-01-15',expectedIdentification:'123400012346',expectedWallet:'109'}}});assert.equal(message.error,undefined);assert.equal(message.result.bank.code,'341');assert.equal(message.result.titleCount,3);assert.equal(message.result.summary.errors,0);assert.equal(message.result.totalCents,'60000');assert.ok(message.result.checks.every(c=>!c.reference.includes('Safra')));});

import {makeSantanderDemo} from '../js/banks/santander-demo.js';
test('worker empacotado executa Santander com transmissão de 20 posições',async()=>{let message;const self={postMessage:data=>{message=data;}};const source=await readFile(new URL('../js/validation-worker.bundle.js',import.meta.url),'utf8');await new vm.Script(source).runInNewContext({self,TextDecoder,TextEncoder,Uint8Array,Date,URL});await self.onmessage({data:{bytes:new TextEncoder().encode(makeSantanderDemo()),options:{bank:'033',layout:'400',referenceDate:'2030-01-15',expectedIdentification:'12340012345600123456',expectedWallet:'5'}}});assert.equal(message.error,undefined);assert.equal(message.result.bank.code,'033');assert.equal(message.result.summary.errors,0);assert.equal(message.result.titleCount,3);assert.equal(message.result.totalCents,'60000');});
